mapper.select:
SELECT t.merchant_code AS merchantCode, COALESCE(m.merchant_name, '알 수 없음') AS merchantName,
DATE_FORMAT(t.payment_date, '%Y-%m') AS paymentDate,
DATE(t.payment_date) AS paymentDate,
COUNT(CASE WHEN t.status IN ('S', 'P') THEN 1 END) AS transactionCount,
ROUND( (COUNT(CASE WHEN t.status IN ('S', 'P') THEN 1 END) * 100.0) / NULLIF(( SELECT COUNT(*) FROM T_TransactionHistory t2 WHERE t2.status IN ('S', 'P')
AND t2.payment_date BETWEEN #{startDate} AND #{endDate}
), 0) , 2) AS transactionRatio,
SUM(CASE WHEN t.status IN ('S', 'P') THEN t.amount_used ELSE 0 END) AS totalAmount,
COUNT(CASE WHEN t.status = 'R' THEN 1 END) AS refundCount,
SUM(CASE WHEN t.status = 'R' THEN t.amount_used ELSE 0 END) AS refundAmount,
( SUM(CASE WHEN t.status IN ('S', 'P') THEN t.amount_used ELSE 0 END) - SUM(CASE WHEN t.status = 'R' THEN t.amount_used ELSE 0 END) ) AS netAmount,
ROUND( ( ( SUM(CASE WHEN t.status IN ('S', 'P') THEN t.amount_used ELSE 0 END) - SUM(CASE WHEN t.status = 'R' THEN t.amount_used ELSE 0 END) ) * 100.0 ) / NULLIF(( SELECT SUM(CASE WHEN t3.status IN ('S', 'P') THEN t3.amount_used ELSE 0 END) - SUM(CASE WHEN t3.status = 'R' THEN t3.amount_used ELSE 0 END) FROM T_TransactionHistory t3
WHERE t3.payment_date BETWEEN #{startDate} AND #{endDate}
), 0) , 2) AS ratioPercentage
FROM T_TransactionHistory t LEFT JOIN T_Merchant m ON t.merchant_code = m.merchant_code LEFT JOIN T_Brand b ON m.brand_code = b.brand_code
WHERE 1=1
AND t.payment_date BETWEEN #{startDate} AND #{endDate}
AND t.merchant_code = #{merchantCode}
AND b.category_code = #{categoryCode}
AND b.brand_code = #{brandCode}
GROUP BY t.merchant_code, m.merchant_name, DATE_FORMAT(t.payment_date, '%Y-%m')
GROUP BY t.merchant_code, m.merchant_name, DATE(t.payment_date)
ORDER BY transactionCount ASC ORDER BY transactionCount DESC
ORDER BY totalAmount ASC ORDER BY totalAmount DESC
ORDER BY refundCount ASC ORDER BY refundCount DESC
ORDER BY netAmount ASC ORDER BY netAmount DESC
ORDER BY ratioPercentage ASC ORDER BY ratioPercentage DESC
ORDER BY transactionRatio ASC ORDER BY transactionRatio DESC
ORDER BY paymentDate ASC ORDER BY paymentDate DESC
LIMIT #{size} OFFSET #{offset}

SELECT COUNT(*) FROM (
SELECT 1
FROM T_TransactionHistory t
LEFT JOIN T_Merchant m ON t.merchant_code = m.merchant_code
LEFT JOIN T_Brand b ON m.brand_code = b.brand_code   

WHERE 1=1

    AND t.payment_date BETWEEN #{startDate} AND #{endDate}



    AND t.merchant_code = #{merchantCode}



    AND b.category_code = #{categoryCode}




    AND b.brand_code = #{brandCode}




        GROUP BY t.merchant_code, DATE_FORMAT(t.payment_date, '%Y-%m')


        GROUP BY t.merchant_code, DATE(t.payment_date)


) AS sub
